// Buddy Beast (früher Pixelmonster) Online-Treffpunkt – Cloudflare Worker mit D1-Datenbank (Binding-Name: DB)
// Speichert Spieler, Freundschaften, Monster-Profile, Gast-Besuche und Quest-Belohnungen.

const CORS={'Access-Control-Allow-Origin':'*','Access-Control-Allow-Methods':'GET,POST,OPTIONS','Access-Control-Allow-Headers':'Content-Type,Authorization'};
const json=(data,status=200)=>new Response(JSON.stringify(data),{status,headers:{'Content-Type':'application/json',...CORS}});
const fail=(msg,status=400)=>json({error:msg},status);
const CODE_CHARS='ABCDEFGHJKLMNPQRSTUVWXYZ23456789';
const MAX_MONSTER=8000,MAX_STATUS=6000,MAX_SPRITE=120000;
const REMOTE_CMDS=['feed','snack','play','clean','sleep','med'];
const CHAT_PER_DAY=80,MAX_SAVE=500000;
// Das ganze Spiel fürs Handy kommt immer frisch aus dem GitHub-Ordner „update“
const GAME_URL='https://raw.githubusercontent.com/Enchio86/Pixelmonster/main/update/pixelmonster.html';
const PWA_HEAD='<link rel="manifest" href="/handy/manifest.json"><link rel="icon" href="/handy/icon-192.png"><link rel="apple-touch-icon" href="/handy/icon-192.png"><meta name="theme-color" content="#120e18"><meta name="mobile-web-app-capable" content="yes"><meta name="apple-mobile-web-app-capable" content="yes"><meta name="apple-mobile-web-app-title" content="Buddy Beast"><meta name="apple-mobile-web-app-status-bar-style" content="black-translucent">';
const PWA_BODY="<script>if('serviceWorker'in navigator)navigator.serviceWorker.register('/handy/sw.js',{scope:'/handy/'}).catch(()=>{})</script>";
async function gameHtml(env){
  let html=env.GAME_HTML;
  if(!html){const r=await fetch(env.GAME_URL||GAME_URL,{cf:{cacheTtl:300,cacheEverything:true}});if(!r.ok)return null;html=await r.text()}
  return html.replace('</head>',PWA_HEAD+'</head>').replace('</body>',PWA_BODY+'</body>');
}

// ---------- Mit dem Monster reden ----------
// Nimmt Claude, wenn ANTHROPIC_API_KEY als Secret gesetzt ist, sonst die kostenlose Cloudflare-KI (Binding „AI“)
const STAGE_NAMES=['Ei','Baby','Jugendlich','Erwachsen'];
const lvl=(v,lo,hi)=>v<20?lo:v>75?hi:null;
function persona(p){
  const n=clean(p.name,20)||'Pimon',st=STAGE_NAMES[p.stage]||'Baby',bond=+p.bond||50;
  const feel=[lvl(+p.hunger,'Du hast großen Hunger und denkst ständig ans Essen.','Du bist pappsatt.'),lvl(+p.mood,'Du bist schlecht gelaunt und etwas beleidigt.','Du bist super gut gelaunt.'),
    lvl(+p.energy,'Du bist todmüde und gähnst.','Du steckst voller Energie.'),lvl(+p.clean,'Du fühlst dich schmutzig und es juckt.',null),lvl(+p.health,'Du fühlst dich krank und schwach.',null),
    p.sick&&'Du bist krank und brauchst Medizin.',p.poop>0&&'Neben dir liegen Häufchen, das ist dir peinlich.',p.sleeping&&'Du wurdest gerade im Schlaf angesprochen und bist verschlafen.',
    p.pension&&'Du bist gerade in der Monster-Pension und erholst dich.',p.quest&&'Du bist gerade unterwegs auf einer Quest.'].filter(Boolean);
  const voice=p.stage<=1?'Du bist noch ein Baby: kurze, einfache Sätze, verspielt und neugierig.':p.stage===2?'Du bist ein Jugendlicher: frech, übermütig, willst stärker werden.':'Du bist erwachsen: selbstbewusst, stolz auf deine Stärke, manchmal weise.';
  const rel=bond>=80?'Du liebst deinen Besitzer über alles.':bond>=50?'Du magst deinen Besitzer.':bond>=25?'Du bist deinem Besitzer gegenüber noch etwas vorsichtig.':'Du fühlst dich von deinem Besitzer vernachlässigt und zeigst das auch.';
  return`Du bist ${n}, ein Monster aus dem Tamagotchi-artigen Spiel „Buddy Beast“. Du sprichst mit deinem Besitzer ${clean(p.owner,20)||''}.
Über dich: Art ${clean(p.species,40)}, Familie ${clean(p.family,30)}, Element ${clean(p.element,20)}, Stufe ${st}, Level ${+p.level||1}${p.title?`, Titel ${clean(p.title,20)}`:''}${p.wins?`, ${+p.wins} gewonnene Kämpfe`:''}.
Charakter: ${clean(p.trait,30)} (${clean(p.traitDesc,120)}).
${voice} ${rel}
So geht es dir gerade: ${feel.length?feel.join(' '):'Dir geht es gut.'}
Regeln:
- Antworte immer auf Deutsch, in der Ich-Form, als dieses Monster. Bleib in deiner Rolle.
- Antworte kurz: höchstens 2 bis 3 Sätze. Benutze ab und zu ein Monster-Geräusch, das zu deinem Element passt, und höchstens ein Emoji.
- Lass deine Gefühle und Bedürfnisse von oben in die Antwort einfließen, ohne Zahlen zu nennen.
- Du lebst in der Welt von Buddy Beast. Du kannst dich nicht selbst füttern oder Dinge im Spiel auslösen, aber du kannst darum bitten.
- Bleib freundlich und kindgerecht, auch wenn du schlecht gelaunt bist.`;
}
async function chatReply(env,db,player,profile,history){
  const day=dayId();
  await db.prepare('INSERT INTO chatcount(player,day,n) VALUES(?,?,1) ON CONFLICT(player,day) DO UPDATE SET n=n+1').bind(player,day).run();
  const used=(await db.prepare('SELECT n FROM chatcount WHERE player=? AND day=?').bind(player,day).first())?.n||0;
  if(used>CHAT_PER_DAY)return{error:'Dein Monster ist vom vielen Reden heiser. Morgen geht es weiter.'};
  // Verlauf bereinigen: höchstens 12 Nachrichten, abwechselnd, beginnt beim Spieler, endet mit dem Spieler
  let msgs=(Array.isArray(history)?history:[]).slice(-12).map(m=>({role:m.role==='assistant'?'assistant':'user',content:clean(m.content,500)})).filter(m=>m.content);
  while(msgs.length&&msgs[0].role!=='user')msgs.shift();
  msgs=msgs.filter((m,i)=>i===0||m.role!==msgs[i-1].role);
  if(!msgs.length||msgs[msgs.length-1].role!=='user')return{error:'Schreib deinem Monster zuerst etwas.'};
  const system=persona(profile||{});let text='';
  if(env.ANTHROPIC_API_KEY){
    const r=await fetch('https://api.anthropic.com/v1/messages',{method:'POST',headers:{'content-type':'application/json','x-api-key':env.ANTHROPIC_API_KEY,'anthropic-version':'2026-10-21','anthropic-beta':'server-side-fallback-2026-07-01'},
      body:JSON.stringify({model:env.CLAUDE_MODEL||'claude-opus-5-5',max_tokens:2000,system,messages:msgs,output_config:{effort:'low'},fallbacks:'default'})});
    const d=await r.json().catch(()=>({}));
    if(!r.ok)return{error:r.status===401?'Der Claude-Schlüssel stimmt nicht.':r.status===429?'Die KI ist gerade überlastet. Versuch es gleich noch mal.':'Die KI antwortet gerade nicht ('+r.status+').'};
    text=d.stop_reason==='refusal'?'':(d.content||[]).filter(b=>b.type==='text').map(b=>b.text).join('');
  }else if(env.AI){
    const d=await env.AI.run(env.AI_MODEL||'@cf/meta/llama-3.3-70b-instruct-fp8-fast',{messages:[{role:'system',content:system},...msgs],max_tokens:220});
    text=d?.response||'';
  }else return{error:'Die KI ist auf dem Server noch nicht eingeschaltet.'};
  text=String(text).trim().slice(0,600)||'*legt den Kopf schief und schaut dich fragend an*';
  return{reply:text,left:Math.max(0,CHAT_PER_DAY-used)};
}

const BOSS_HP=1200,BOSS_MAX_HIT=700;
function weekId(d=new Date()){
  const t=new Date(Date.UTC(d.getFullYear(),d.getMonth(),d.getDate())),day=t.getUTCDay()||7;t.setUTCDate(t.getUTCDate()+4-day);
  const y=t.getUTCFullYear();return`${y}-W${String(Math.ceil(((t-Date.UTC(y,0,1))/864e5+1)/7)).padStart(2,'0')}`;
}
async function bossState(db,week,me){
  const hits=(await db.prepare('SELECT b.player,b.dmg,b.claimed,p.name FROM bosshits b JOIN players p ON p.id=b.player WHERE b.week=?').bind(week).all()).results;
  const mine=hits.find(h=>h.player===me);
  return{week,hp:BOSS_HP,dmg:hits.reduce((a,h)=>a+h.dmg,0),hit:mine?mine.dmg:null,claimed:!!mine?.claimed,players:hits.map(h=>h.name)};
}

// Raid des Monats: ein riesiger Boss, alle Spieler zusammen, jeder einmal pro Tag (UTC)
const RAID_HP=20000,RAID_MAX_HIT=1500;
const monthId=(d=new Date())=>d.toISOString().slice(0,7),dayId=(d=new Date())=>d.toISOString().slice(0,10);
async function raidState(db,month,me){
  const hits=(await db.prepare('SELECT r.player,r.day,r.dmg,p.name FROM raidhits r JOIN players p ON p.id=r.player WHERE r.month=?').bind(month).all()).results;
  const mine=hits.filter(h=>h.player===me),names=[...new Set(hits.map(h=>h.name))];
  const claimed=!!(await db.prepare('SELECT 1 FROM raidclaims WHERE month=? AND player=?').bind(month,me).first());
  return{month,hp:RAID_HP,dmg:hits.reduce((a,h)=>a+h.dmg,0),fights:mine.length,myDmg:mine.reduce((a,h)=>a+h.dmg,0),today:mine.some(h=>h.day===dayId()),claimed,players:names};
}

let ready=false;
async function init(db){
  if(ready)return;
  await db.batch([
    db.prepare('CREATE TABLE IF NOT EXISTS players(id TEXT PRIMARY KEY,secret TEXT,name TEXT,code TEXT UNIQUE,monster TEXT,updated INTEGER)'),
    db.prepare('CREATE TABLE IF NOT EXISTS friends(a TEXT,b TEXT,PRIMARY KEY(a,b))'),
    db.prepare('CREATE TABLE IF NOT EXISTS guests(id TEXT PRIMARY KEY,owner TEXT,host TEXT,monster TEXT,created INTEGER)'),
    db.prepare('CREATE TABLE IF NOT EXISTS returns(id TEXT PRIMARY KEY,owner TEXT,data TEXT,created INTEGER)'),
    db.prepare('CREATE TABLE IF NOT EXISTS bosshits(week TEXT,player TEXT,dmg INTEGER,claimed INTEGER DEFAULT 0,PRIMARY KEY(week,player))'),
    db.prepare('CREATE TABLE IF NOT EXISTS raidhits(month TEXT,player TEXT,day TEXT,dmg INTEGER,PRIMARY KEY(month,player,day))'),
    db.prepare('CREATE TABLE IF NOT EXISTS raidclaims(month TEXT,player TEXT,PRIMARY KEY(month,player))'),
    db.prepare('CREATE TABLE IF NOT EXISTS pairs(code TEXT PRIMARY KEY,player TEXT,expires INTEGER)'),
    db.prepare('CREATE TABLE IF NOT EXISTS remotes(token TEXT PRIMARY KEY,player TEXT,created INTEGER)'),
    db.prepare('CREATE TABLE IF NOT EXISTS rstatus(player TEXT PRIMARY KEY,data TEXT,sprite TEXT,updated INTEGER)'),
    db.prepare('CREATE TABLE IF NOT EXISTS cmds(id INTEGER PRIMARY KEY AUTOINCREMENT,player TEXT,cmd TEXT,created INTEGER)'),
    db.prepare('CREATE TABLE IF NOT EXISTS chatcount(player TEXT,day TEXT,n INTEGER,PRIMARY KEY(player,day))'),
    db.prepare('CREATE TABLE IF NOT EXISTS saves(player TEXT PRIMARY KEY,data TEXT,rev INTEGER,updated INTEGER)')
  ]);
  ready=true;
}
function newCode(){let c='';const b=crypto.getRandomValues(new Uint8Array(6));for(const x of b)c+=CODE_CHARS[x%CODE_CHARS.length];return c.slice(0,3)+'-'+c.slice(3)}
const clean=(s,n)=>String(s||'').replace(/[\u0000-\u001f]/g,'').trim().slice(0,n);

async function auth(req,db){
  const [id,secret]=(req.headers.get('Authorization')||'').replace('Bearer ','').split('.');
  if(!id||!secret)return null;
  const p=await db.prepare('SELECT * FROM players WHERE id=?').bind(id).first();
  return p&&p.secret===secret?p:null;
}
async function state(db,me){
  const friends=(await db.prepare('SELECT p.id,p.name,p.code,p.monster,p.updated FROM friends f JOIN players p ON p.id=f.b WHERE f.a=? ORDER BY p.name').bind(me.id).all()).results
    .map(f=>({...f,monster:f.monster?JSON.parse(f.monster):null}));
  const guests=(await db.prepare('SELECT g.id,g.owner,g.monster,g.created,p.name AS ownerName FROM guests g JOIN players p ON p.id=g.owner WHERE g.host=?').bind(me.id).all()).results
    .map(g=>({...g,monster:JSON.parse(g.monster)}));
  const outgoing=(await db.prepare('SELECT g.id,g.host,g.created,p.name AS hostName FROM guests g JOIN players p ON p.id=g.host WHERE g.owner=?').bind(me.id).all()).results;
  const returns=(await db.prepare('SELECT id,data FROM returns WHERE owner=?').bind(me.id).all()).results.map(r=>({id:r.id,...JSON.parse(r.data)}));
  const remotes=(await db.prepare('SELECT COUNT(*) AS n FROM remotes WHERE player=?').bind(me.id).first())?.n||0;
  return{me:{id:me.id,name:me.name,code:me.code},friends,guests,outgoing,returns,remotes};
}

export default{
  async fetch(req,env){
    try{return await handle(req,env)}
    catch(e){return fail('Serverfehler: '+(e&&e.message||e),500)}
  }
};

async function handle(req,env){
  {
    if(req.method==='OPTIONS')return new Response(null,{headers:CORS});
    const db=env.DB;if(!db)return fail('Die Datenbank ist nicht verbunden (Binding „DB“ fehlt).',500);
    await init(db);
    const path=new URL(req.url).pathname.replace(/\/+$/,'');
    const body=req.method==='POST'?await req.json().catch(()=>({})):{};
    if(path===''||path==='/ping')return json({ok:true,game:'pixelmonster'});
    if(new URL(req.url).pathname==='/handy')return Response.redirect(new URL('/handy/',req.url).href,301);
    if(path==='/handy'){const h=await gameHtml(env);return h?new Response(h,{headers:{'Content-Type':'text/html; charset=utf-8','Cache-Control':'no-cache'}}):fail('Das Spiel konnte gerade nicht geladen werden.',502)}
    if(path==='/fernbedienung')return new Response(HANDY_HTML,{headers:{'Content-Type':'text/html; charset=utf-8','Cache-Control':'no-cache'}});
    if(path==='/handy/manifest.json')return new Response(JSON.stringify(MANIFEST),{headers:{'Content-Type':'application/manifest+json','Cache-Control':'max-age=3600'}});
    if(path==='/handy/sw.js')return new Response(SW_JS,{headers:{'Content-Type':'text/javascript','Cache-Control':'no-cache'}});
    if(path==='/handy/icon-192.png'||path==='/handy/icon-512.png'){const b=atob(path.includes('192')?ICON_192:ICON_512),a=new Uint8Array(b.length);for(let i=0;i<b.length;i++)a[i]=b.charCodeAt(i);
      return new Response(a,{headers:{'Content-Type':'image/png','Cache-Control':'max-age=86400'}})}

    // Handy-Fernbedienung: koppeln per Code, dann Status lesen und Befehle schicken
    if(path==='/pair/claim'){
      const code=clean(body.code,7).toUpperCase().replace(/[^A-Z0-9]/g,'');
      const p=await db.prepare('SELECT * FROM pairs WHERE code=?').bind(code).first();
      if(!p||p.expires<Date.now())return fail('Der Code ist falsch oder abgelaufen. Lass dir in der PC-App einen neuen zeigen.',404);
      const token=crypto.randomUUID().replace(/-/g,'')+crypto.randomUUID().replace(/-/g,'');
      await db.batch([db.prepare('DELETE FROM pairs WHERE code=?').bind(code),db.prepare('INSERT INTO remotes(token,player,created) VALUES(?,?,?)').bind(token,p.player,Date.now())]);
      const pl=await db.prepare('SELECT id,secret FROM players WHERE id=?').bind(p.player).first();
      return json({token,id:pl.id,secret:pl.secret});
    }
    if(path.startsWith('/r/')){
      const tok=(req.headers.get('Authorization')||'').replace('Remote ','');
      const r=tok&&await db.prepare('SELECT player FROM remotes WHERE token=?').bind(tok).first();
      if(!r)return fail('Dieses Handy ist nicht mehr gekoppelt.',401);
      if(path==='/r/chat'){
        const st=await db.prepare('SELECT data FROM rstatus WHERE player=?').bind(r.player).first();
        if(!st)return fail('Dein Monster ist noch nicht online. Ist die PC-App an?');
        const d=await chatReply(env,db,r.player,JSON.parse(st.data),body.messages);if(d.error)return fail(d.error,503);
        await db.prepare('INSERT INTO cmds(player,cmd,created) VALUES(?,?,?)').bind(r.player,'talk',Date.now()).run();
        return json(d);
      }
      if(path==='/r/cmd'){
        if(!REMOTE_CMDS.includes(body.cmd))return fail('Unbekannter Befehl.');
        const n=(await db.prepare('SELECT COUNT(*) AS n FROM cmds WHERE player=?').bind(r.player).first())?.n||0;
        if(n>=10)return fail('Es warten schon 10 Befehle. Ist die PC-App an?');
        await db.prepare('INSERT INTO cmds(player,cmd,created) VALUES(?,?,?)').bind(r.player,body.cmd,Date.now()).run();
      }
      const st=await db.prepare('SELECT data,sprite,updated FROM rstatus WHERE player=?').bind(r.player).first();
      const pending=(await db.prepare('SELECT COUNT(*) AS n FROM cmds WHERE player=?').bind(r.player).first())?.n||0;
      return json({status:st?JSON.parse(st.data):null,sprite:st?.sprite||null,updated:st?.updated||0,now:Date.now(),pending});
    }

    if(path==='/register'){
      const name=clean(body.name,20)||'Spieler',id=crypto.randomUUID(),secret=crypto.randomUUID().replace(/-/g,'');
      let code;for(let i=0;i<5;i++){code=newCode();if(!await db.prepare('SELECT 1 FROM players WHERE code=?').bind(code).first())break}
      await db.prepare('INSERT INTO players(id,secret,name,code,monster,updated) VALUES(?,?,?,?,NULL,?)').bind(id,secret,name,code,Date.now()).run();
      return json({id,secret,code,name});
    }

    const me=await auth(req,db);if(!me)return fail('Nicht angemeldet.',401);

    if(path==='/state')return json(await state(db,me));
    if(path==='/sync'){
      const m=body.monster?JSON.stringify(body.monster):null;
      if(m&&m.length>MAX_MONSTER)return fail('Monsterdaten zu groß.');
      const name=clean(body.name,20)||me.name;
      await db.prepare('UPDATE players SET monster=COALESCE(?,monster),name=?,updated=? WHERE id=?').bind(m,name,Date.now(),me.id).run();
      let cmds=[];
      if(body.remote){
        const d=JSON.stringify(body.remote.status||{}),sp=typeof body.remote.sprite==='string'&&body.remote.sprite.startsWith('data:image/')?body.remote.sprite:null;
        if(d.length>MAX_STATUS||(sp&&sp.length>MAX_SPRITE))return fail('Statusdaten zu groß.');
        await db.prepare('INSERT INTO rstatus(player,data,sprite,updated) VALUES(?,?,?,?) ON CONFLICT(player) DO UPDATE SET data=excluded.data,sprite=COALESCE(excluded.sprite,rstatus.sprite),updated=excluded.updated').bind(me.id,d,sp,Date.now()).run();
        cmds=(await db.prepare('SELECT id,cmd,created FROM cmds WHERE player=? ORDER BY id').bind(me.id).all()).results;
        if(cmds.length)await db.prepare('DELETE FROM cmds WHERE player=? AND id<=?').bind(me.id,cmds[cmds.length-1].id).run();
      }
      return json({...await state(db,{...me,name}),cmds});
    }
    if(path==='/chat'){const d=await chatReply(env,db,me.id,body.monster,body.messages);return d.error?fail(d.error,503):json(d)}
    if(path==='/pair/new'){
      let code='';for(const x of crypto.getRandomValues(new Uint8Array(6)))code+=CODE_CHARS[x%CODE_CHARS.length];
      await db.batch([db.prepare('DELETE FROM pairs WHERE player=? OR expires<?').bind(me.id,Date.now()),db.prepare('INSERT INTO pairs(code,player,expires) VALUES(?,?,?)').bind(code,me.id,Date.now()+6e5)]);
      return json({code,expires:Date.now()+6e5});
    }
    if(path==='/pair/reset'){
      // Neues Geheimnis: gekoppelte Handys verlieren den Zugang, nur das Gerät, das entkoppelt, bekommt es
      const secret=crypto.randomUUID().replace(/-/g,'');
      await db.batch([db.prepare('DELETE FROM remotes WHERE player=?').bind(me.id),db.prepare('DELETE FROM cmds WHERE player=?').bind(me.id),db.prepare('UPDATE players SET secret=? WHERE id=?').bind(secret,me.id)]);
      return json({...await state(db,me),secret});
    }
    // Spielstand in der Cloud, damit PC und Handy dasselbe Monster pflegen. rev zählt jede Änderung hoch;
    // wer mit einem veralteten Stand speichert, bekommt den neueren zurück (409) und übernimmt ihn
    if(path==='/save'){
      const cur=await db.prepare('SELECT data,rev,updated FROM saves WHERE player=?').bind(me.id).first();
      if(req.method!=='POST')return json(cur?{rev:cur.rev,updated:cur.updated,data:+new URL(req.url).searchParams.get('have')===cur.rev?null:JSON.parse(cur.data)}:{rev:0,data:null});
      const d=JSON.stringify(body.data||null);if(!body.data||d.length>MAX_SAVE)return fail('Spielstand ungültig oder zu groß.');
      if(cur&&!body.force&&+body.base!==cur.rev)return json({error:'conflict',rev:cur.rev,data:JSON.parse(cur.data)},409);
      const rev=(cur?.rev||0)+1;
      await db.prepare('INSERT INTO saves(player,data,rev,updated) VALUES(?,?,?,?) ON CONFLICT(player) DO UPDATE SET data=excluded.data,rev=excluded.rev,updated=excluded.updated').bind(me.id,d,rev,Date.now()).run();
      return json({rev});
    }
    if(path==='/friend'){
      const code=clean(body.code,7).toUpperCase().replace(/^([A-Z0-9]{3})([A-Z0-9]{3})$/,'$1-$2');
      const f=await db.prepare('SELECT id,name FROM players WHERE code=?').bind(code).first();
      if(!f)return fail('Diesen Freundescode gibt es nicht.',404);
      if(f.id===me.id)return fail('Das ist dein eigener Code.');
      await db.batch([db.prepare('INSERT OR IGNORE INTO friends(a,b) VALUES(?,?)').bind(me.id,f.id),db.prepare('INSERT OR IGNORE INTO friends(a,b) VALUES(?,?)').bind(f.id,me.id)]);
      return json({ok:true,name:f.name,...await state(db,me)});
    }
    if(path==='/unfriend'){
      await db.batch([db.prepare('DELETE FROM friends WHERE a=? AND b=?').bind(me.id,body.id),db.prepare('DELETE FROM friends WHERE a=? AND b=?').bind(body.id,me.id)]);
      return json(await state(db,me));
    }
    if(path==='/visit'){
      const isFriend=await db.prepare('SELECT 1 FROM friends WHERE a=? AND b=?').bind(me.id,body.to).first();
      if(!isFriend)return fail('Ihr seid noch keine Freunde.');
      if(!me.monster)return fail('Dein Monster ist noch nicht online.');
      if(await db.prepare('SELECT 1 FROM guests WHERE owner=? AND host=?').bind(me.id,body.to).first())return fail('Dein Monster ist dort schon zu Besuch.');
      await db.prepare('INSERT INTO guests(id,owner,host,monster,created) VALUES(?,?,?,?,?)').bind(crypto.randomUUID(),me.id,body.to,me.monster,Date.now()).run();
      return json(await state(db,me));
    }
    if(path==='/return'){
      const g=await db.prepare('SELECT * FROM guests WHERE id=? AND host=?').bind(body.guest,me.id).first();
      if(!g)return fail('Diesen Gast gibt es nicht mehr.',404);
      const r=body.result||{},data=JSON.stringify({host:me.name,monsterName:clean(r.monsterName,20),quest:clean(r.quest,30),ok:!!r.ok,
        xp:Math.min(Math.max(+r.xp||0,0),300),coins:Math.min(Math.max(+r.coins||0,0),200),items:{beere:Math.min(+r.items?.beere||0,5),trank:Math.min(+r.items?.trank||0,5)}});
      await db.batch([db.prepare('DELETE FROM guests WHERE id=?').bind(g.id),db.prepare('INSERT INTO returns(id,owner,data,created) VALUES(?,?,?,?)').bind(crypto.randomUUID(),g.owner,data,Date.now())]);
      return json(await state(db,me));
    }
    if(path==='/claim'){
      const r=await db.prepare('SELECT data FROM returns WHERE id=? AND owner=?').bind(body.id,me.id).first();
      if(!r)return fail('Schon abgeholt.',404);
      await db.prepare('DELETE FROM returns WHERE id=?').bind(body.id).run();
      return json({id:body.id,...JSON.parse(r.data)});
    }
    // Wochen-Boss: alle Spieler kämpfen gemeinsam, jeder einmal pro Woche
    if(path==='/boss'||path==='/boss/hit'||path==='/boss/claim'){
      // Die Woche des Spielers zählt, solange sie höchstens einen halben Tag von der Serverzeit abweicht (Zeitzonen)
      const near=[-1,0,1].map(k=>weekId(new Date(Date.now()+k*432e5)));
      const week=near.includes(body.week)?body.week:weekId();
      if(path==='/boss/hit'){
        if(body.week!==week)return fail('Diese Boss-Woche ist vorbei.');
        const dmg=Math.min(Math.max(Math.round(+body.dmg||0),0),BOSS_MAX_HIT);
        const r=await db.prepare('INSERT OR IGNORE INTO bosshits(week,player,dmg) VALUES(?,?,?)').bind(week,me.id,dmg).run();
        if(!(r.meta?.changes??r.changes))return fail('Du hast diese Woche schon gegen den Boss gekämpft.');
      }
      if(path==='/boss/claim'){
        const st=await bossState(db,week,me.id);
        if(st.dmg<st.hp)return fail('Der Boss ist noch nicht besiegt.');
        if(st.hit==null)return fail('Du hast diese Woche nicht mitgekämpft.');
        if(st.claimed)return fail('Belohnung schon abgeholt.');
        await db.prepare('UPDATE bosshits SET claimed=1 WHERE week=? AND player=?').bind(week,me.id).run();
      }
      return json(await bossState(db,week,me.id));
    }
    if(path==='/raid'||path==='/raid/hit'||path==='/raid/claim'){
      const near=[-1,0,1].map(k=>monthId(new Date(Date.now()+k*432e5)));
      const month=near.includes(body.month)?body.month:monthId();
      if(path==='/raid/hit'){
        if(body.month!==month)return fail('Dieser Raid ist vorbei.');
        const st=await raidState(db,month,me.id);if(st.dmg>=st.hp)return fail('Der Raidboss ist schon besiegt.');
        const dmg=Math.min(Math.max(Math.round(+body.dmg||0),0),RAID_MAX_HIT);
        const r=await db.prepare('INSERT OR IGNORE INTO raidhits(month,player,day,dmg) VALUES(?,?,?,?)').bind(month,me.id,dayId(),dmg).run();
        if(!(r.meta?.changes??r.changes))return fail('Du hast heute schon gegen den Raidboss gekämpft.');
      }
      if(path==='/raid/claim'){
        const st=await raidState(db,month,me.id);
        if(st.dmg<st.hp)return fail('Der Raidboss ist noch nicht besiegt.');
        if(!st.fights)return fail('Du hast in diesem Raid nicht mitgekämpft.');
        const r=await db.prepare('INSERT OR IGNORE INTO raidclaims(month,player) VALUES(?,?)').bind(month,me.id).run();
        if(!(r.meta?.changes??r.changes))return fail('Beute schon abgeholt.');
      }
      return json(await raidState(db,month,me.id));
    }
    return fail('Unbekannte Adresse.',404);
  }
}

// ---------- Handy-App: Manifest, Service Worker und App-Symbole ----------
const MANIFEST={name:'Buddy Beast',short_name:'Buddy Beast',description:'Dein Buddy Beast für unterwegs',start_url:'/handy/',scope:'/handy/',display:'standalone',orientation:'portrait',
  background_color:'#120e18',theme_color:'#120e18',lang:'de',icons:[{src:'/handy/icon-192.png',sizes:'192x192',type:'image/png',purpose:'any maskable'},{src:'/handy/icon-512.png',sizes:'512x512',type:'image/png',purpose:'any maskable'}]};
// Lädt immer frisch vom Server und zeigt ohne Netz die zuletzt gespeicherte Seite
const SW_JS=`self.addEventListener('install',e=>{self.skipWaiting();e.waitUntil(caches.open('pxm-handy').then(c=>c.add('/handy/')))});
self.addEventListener('activate',e=>e.waitUntil(self.clients.claim()));
self.addEventListener('fetch',e=>{if(e.request.mode==='navigate')e.respondWith(fetch(e.request).then(r=>{const c=r.clone();caches.open('pxm-handy').then(x=>x.put('/handy/',c));return r}).catch(()=>caches.match('/handy/')))});`;
const ICON_192='';
const ICON_512='';

// ---------- Handy-Seite (automatisch aus handy.html eingefügt) ----------
const HANDY_HTML="<!doctype html>\n<html lang=\"de\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1, viewport-fit=cover\">\n<meta name=\"theme-color\" content=\"#120e18\">\n<meta name=\"apple-mobile-web-app-capable\" content=\"yes\">\n<meta name=\"mobile-web-app-capable\" content=\"yes\">\n<title>Buddy Beast Fernbedienung</title>\n<link rel=\"manifest\" href=\"/handy/manifest.json\">\n<link rel=\"icon\" href=\"/handy/icon-192.png\">\n<link rel=\"apple-touch-icon\" href=\"/handy/icon-192.png\">\n<meta name=\"apple-mobile-web-app-title\" content=\"Buddy Beast\">\n<meta name=\"apple-mobile-web-app-status-bar-style\" content=\"black-translucent\">\n<style>\n:root{--bg:#120e18;--panel:#1f1a28;--panel2:#2c2538;--text:#f3ecdf;--muted:#a99fb8;--accent:#e2b65c;--good:#5fd38a;--bad:#ff6b6b;--warn:#ffb347}\n*{box-sizing:border-box}\nbody{margin:0;background:radial-gradient(circle at 50% 0,#2a2036,var(--bg) 60%) fixed;background-color:var(--bg);color:var(--text);font:16px/1.4 system-ui,-apple-system,Segoe UI,Roboto,sans-serif;min-height:100vh;padding:16px 16px calc(24px + env(safe-area-inset-bottom))}\nmain{max-width:460px;margin:0 auto}\nh1{font:700 20px Georgia,serif;color:var(--accent);margin:4px 0 14px;text-align:center}\n.card{background:var(--panel);border:1px solid #3a3048;border-radius:16px;padding:14px;margin-bottom:12px}\n.muted{color:var(--muted);font-size:14px}\ninput{width:100%;padding:14px;border-radius:12px;border:1px solid #4a3e5c;background:var(--panel2);color:var(--text);font-size:22px;letter-spacing:4px;text-transform:uppercase;text-align:center}\nbutton{font:inherit;color:var(--text);background:var(--panel2);border:1px solid #4a3e5c;border-radius:14px;padding:12px;cursor:pointer;touch-action:manipulation}\nbutton:active{transform:scale(.97)}\nbutton.primary{background:linear-gradient(#e9c477,#b8945a);color:#1a1208;border:0;font-weight:700;width:100%;margin-top:10px}\nbutton:disabled{opacity:.45}\n.mon{display:flex;gap:12px;align-items:center}\n.mon img{width:120px;height:120px;flex:none;background:#17121f;border-radius:14px}\n.mon .t{font-weight:700;font-size:18px}\n.bar{margin:7px 0}\n.bar label{display:flex;justify-content:space-between;font-size:14px;color:var(--muted)}\n.track{height:10px;background:#120e18;border-radius:6px;overflow:hidden}\n.fill{height:100%;border-radius:6px;transition:width .4s}\n.acts{display:grid;grid-template-columns:repeat(3,1fr);gap:10px}\n.acts button{display:flex;flex-direction:column;align-items:center;gap:2px;font-size:28px;padding:12px 4px}\n.acts span{font-size:13px;color:var(--muted)}\n.status{font-size:14px;margin-top:8px}\nul{list-style:none;margin:0;padding:0}\nli{font-size:14px;padding:6px 0;border-bottom:1px solid #2c2538}\nli time{color:var(--muted);margin-right:6px}\n.pill{display:inline-block;background:var(--panel2);border-radius:20px;padding:2px 9px;font-size:13px;margin:4px 4px 0 0}\n#toast{position:fixed;left:16px;right:16px;bottom:calc(20px + env(safe-area-inset-bottom));max-width:428px;margin:0 auto;background:#2c2538;border:1px solid var(--accent);border-radius:12px;padding:12px;text-align:center;opacity:0;transition:opacity .3s;pointer-events:none}\n#toast.on{opacity:1}\na{color:var(--accent)}\n#chatLog{max-height:340px;overflow-y:auto;display:flex;flex-direction:column;gap:8px;margin-bottom:10px}\n.bub{max-width:85%;padding:9px 12px;border-radius:14px;white-space:pre-wrap;word-wrap:break-word}\n.bub.me{align-self:flex-end;background:#3a3150;border-bottom-right-radius:4px}\n.bub.mon{align-self:flex-start;background:#2a2238;border:1px solid #4a3e5c;border-bottom-left-radius:4px}\n.bub.wait{opacity:.7;font-style:italic}\n.chatrow{display:flex;gap:8px}\n.chatrow input{font-size:16px;letter-spacing:0;text-transform:none;text-align:left;padding:12px}\n.chatrow button{flex:none;font-size:20px;padding:10px 14px}\n</style>\n</head>\n<body>\n<main>\n<h1>📱 Buddy Beast</h1>\n<div id=\"app\"></div>\n<div id=\"chat\"></div>\n<div id=\"install\"></div>\n</main>\n<div id=\"toast\"></div>\n<script>\nconst KEY='pixelmonster.remote';\nconst $=s=>document.querySelector(s);\nconst esc=s=>String(s??'').replace(/[&<>\"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','\"':'&quot;',\"'\":'&#39;'}[c]));\nlet token=null,last=null,timer=null,toastT=null;\ntry{token=localStorage.getItem(KEY)}catch(e){}\nfunction toast(m){const t=$('#toast');t.textContent=m;t.classList.add('on');clearTimeout(toastT);toastT=setTimeout(()=>t.classList.remove('on'),2800)}\nasync function api(path,body){\n  let r;\n  try{r=await fetch(path,{method:body?'POST':'GET',headers:{'Content-Type':'application/json',...(token?{Authorization:'Remote '+token}:{})},body:body?JSON.stringify(body):undefined})}\n  catch(e){throw Error('Keine Verbindung. Bist du online?')}\n  const d=await r.json().catch(()=>({error:'Ungültige Antwort vom Server.'}));\n  if(r.status===401&&token){unpairLocal();throw Error(d.error)}\n  if(!r.ok||d.error)throw Error(d.error||'Fehler '+r.status);\n  return d;\n}\nfunction unpairLocal(){token=null;try{localStorage.removeItem(KEY)}catch(e){}clearInterval(timer);$('#chat').innerHTML='';renderPair()}\nfunction renderPair(){\n  $('#app').innerHTML=`<div class=\"card\"><p>Steuere dein Monster vom Handy aus.</p>\n    <ol class=\"muted\" style=\"padding-left:20px\"><li>Öffne am PC die Buddy-Beast-App und klick oben rechts auf <b>⚙️</b>.</li><li>Tippe dort auf <b>📱 Handy koppeln</b>.</li><li>Gib den Code hier ein.</li></ol>\n    <input id=\"code\" maxlength=\"7\" autocomplete=\"off\" placeholder=\"ABC123\">\n    <button class=\"primary\" id=\"pairBtn\">Koppeln</button></div>\n`;\n  $('#pairBtn').onclick=pair;$('#code').onkeydown=e=>{if(e.key==='Enter')pair()};\n}\nasync function pair(){\n  const code=$('#code').value.trim();if(!code)return;\n  try{const d=await api('/pair/claim',{code});token=d.token;try{localStorage.setItem(KEY,token)}catch(e){}toast('Gekoppelt!');start()}\n  catch(e){toast(e.message)}\n}\nconst ACTS=[['feed','🍙','Füttern'],['snack','🍓','Beere'],['play','⚽','Spielen'],['clean','🧽','Putzen'],['sleep','💤','Schlafen'],['med','💊','Medizin']];\nfunction ago(ms){const s=Math.round(ms/1000);return s<60?`vor ${s} s`:s<3600?`vor ${Math.round(s/60)} min`:s<86400?`vor ${Math.round(s/3600)} h`:`vor ${Math.round(s/86400)} Tagen`}\nfunction bar(lbl,v){v=Math.max(0,Math.min(100,v||0));const c=v>50?'var(--good)':v>20?'var(--warn)':'var(--bad)';return`<div class=\"bar\"><label>${lbl}<span>${Math.round(v)}</span></label><div class=\"track\"><div class=\"fill\" style=\"width:${v}%;background:${c}\"></div></div></div>`}\nfunction render(){\n  const d=last;if(!d)return;const s=d.status;\n  if(!s){$('#app').innerHTML=`<div class=\"card\"><p>Gekoppelt! Sobald die PC-App online ist, erscheint hier dein Monster.</p><p class=\"muted\">Die PC-App muss im Tab 🌐 Online verbunden sein.</p></div>${footer()}`;bindFooter();return}\n  const age=d.now-d.updated,live=age<45000;\n  const flags=[s.sick&&'🤒 krank',s.poop&&`💩 ×${s.poop}`,s.sleeping&&'💤 schläft',s.pension&&'🏨 in der Pension',s.quest&&'🧭 auf Quest',s.stage===0&&'🥚 noch ein Ei'].filter(Boolean);\n  $('#app').innerHTML=`<div class=\"card\"><div class=\"mon\">${d.sprite?`<img src=\"${d.sprite}\" alt=\"\">`:''}<div><div class=\"t\">${esc(s.name)}</div><div class=\"muted\">${esc(s.species)} · Lv ${s.level}</div>\n      <div>${flags.map(f=>`<span class=\"pill\">${f}</span>`).join('')}<span class=\"pill\">🍓 ${s.beere}</span></div></div></div>\n    <div class=\"status\">${live?`<span style=\"color:var(--good)\">● PC verbunden</span> <span class=\"muted\">· Stand ${ago(age)}</span>`:`<span style=\"color:var(--warn)\">⚠️ Die PC-App ist gerade nicht online</span> <span class=\"muted\">(zuletzt ${ago(age)}). Befehle warten, bis sie wieder läuft.</span>`}</div>\n    ${d.pending?`<div class=\"status muted\">⏳ ${d.pending} ${d.pending===1?'Befehl ist':'Befehle sind'} unterwegs …</div>`:''}</div>\n    <div class=\"card\">${bar('🍙 Sattheit',s.hunger)+bar('😊 Laune',s.mood)+bar('⚡ Energie',s.energy)+bar('🧽 Sauberkeit',s.clean)+bar('❤️ Gesundheit',s.health)}</div>\n    <div class=\"card acts\">${ACTS.map(([k,i,l])=>`<button data-cmd=\"${k}\">${k==='sleep'&&s.sleeping?'☀️':i}<span>${k==='sleep'&&s.sleeping?'Wecken':l}</span></button>`).join('')}</div>\n    <div class=\"card\"><div class=\"muted\" style=\"margin-bottom:4px\">Tagebuch</div><ul>${(s.log||[]).map(l=>`<li><time>${new Date(l.t).toLocaleTimeString('de-DE',{hour:'2-digit',minute:'2-digit'})}</time>${esc(l.m)}</li>`).join('')}</ul></div>${footer()}`;\n  document.querySelectorAll('[data-cmd]').forEach(b=>b.onclick=()=>send(b.dataset.cmd));bindFooter();\n}\nfunction footer(){return`<p style=\"text-align:center\"><a href=\"#\" id=\"unpair\">Handy entkoppeln</a></p>`}\nfunction bindFooter(){$('#unpair').onclick=e=>{e.preventDefault();if(confirm('Dieses Handy wirklich entkoppeln?'))unpairLocal()}}\nasync function send(cmd){\n  try{last=await api('/r/cmd',{cmd});render();toast(last.now-last.updated<45000?'Gesendet. Kommt in ein paar Sekunden an.':'Gesendet. Kommt an, sobald die PC-App läuft.')}\n  catch(e){toast(e.message)}\n}\nasync function poll(){try{last=await api('/r/status');render();if(!$('#chatLog'))renderChat()}catch(e){if(token)toast(e.message)}}\n// ---------- Reden: Chat mit dem Monster, Antworten werden vorgelesen ----------\nconst CKEY='pixelmonster.chat';let chat=[],chatBusy=false,voiceOff=false;\ntry{chat=JSON.parse(localStorage.getItem(CKEY)||'[]');voiceOff=localStorage.getItem(CKEY+'.voice')==='off'}catch(e){}\nconst SR=window.SpeechRecognition||window.webkitSpeechRecognition;\nfunction saveChat(){try{localStorage.setItem(CKEY,JSON.stringify(chat.slice(-40)))}catch(e){}}\nfunction speak(text){\n  if(voiceOff||!window.speechSynthesis)return;const t=text.replace(/\\*[^*]*\\*/g,'').replace(/[\\u{1F000}-\\u{1FAFF}\\u{2600}-\\u{27BF}]/gu,'').trim();if(!t)return;\n  speechSynthesis.cancel();const u=new SpeechSynthesisUtterance(t);u.lang='de-DE';const v=speechSynthesis.getVoices().find(v=>/^de/i.test(v.lang));if(v)u.voice=v;\n  const st=last?.status?.stage??1;u.pitch=[1.9,1.9,1.4,.7][st]??1;u.rate=[1.15,1.15,1.05,.92][st]??1;speechSynthesis.speak(u);\n}\nfunction renderChat(){\n  const s=last?.status,box=$('#chat');if(!s||!token){box.innerHTML='';return}\n  if(s.stage===0){box.innerHTML='';return}\n  const keep=$('#chatIn')?.value||'';\n  box.innerHTML=`<div class=\"card\"><div class=\"muted\" style=\"margin-bottom:8px\">💬 Mit ${esc(s.name)} reden</div><div id=\"chatLog\">\n    ${chat.length?'':`<div class=\"muted\" style=\"text-align:center\">Sag ${esc(s.name)} hallo!</div>`}\n    ${chat.map(m=>`<div class=\"bub ${m.role==='user'?'me':'mon'}\">${esc(m.content)}</div>`).join('')}${chatBusy?`<div class=\"bub mon wait\">${esc(s.name)} denkt nach …</div>`:''}</div>\n    <div class=\"chatrow\"><input id=\"chatIn\" maxlength=\"300\" placeholder=\"Schreib etwas …\" autocomplete=\"off\">${SR?'<button id=\"micBtn\">🎤</button>':''}<button id=\"sendBtn\" ${chatBusy?'disabled':''}>➤</button></div>\n    <div class=\"muted\" style=\"margin-top:8px;display:flex;justify-content:space-between\"><label><input type=\"checkbox\" id=\"voiceCb\" style=\"width:auto\" ${voiceOff?'':'checked'}> 🔊 Vorlesen</label>${chat.length?'<a href=\"#\" id=\"chatClr\">Verlauf löschen</a>':''}</div></div>`;\n  const log=$('#chatLog');log.scrollTop=log.scrollHeight;$('#chatIn').value=keep;\n  $('#chatIn').onkeydown=e=>{if(e.key==='Enter')sendChat()};$('#sendBtn').onclick=sendChat;\n  $('#voiceCb').onchange=e=>{voiceOff=!e.target.checked;try{localStorage.setItem(CKEY+'.voice',voiceOff?'off':'on')}catch(x){}};\n  if($('#chatClr'))$('#chatClr').onclick=e=>{e.preventDefault();chat=[];saveChat();renderChat()};\n  if($('#micBtn'))$('#micBtn').onclick=()=>{const r=new SR();r.lang='de-DE';$('#micBtn').textContent='👂';\n    r.onresult=e=>{$('#chatIn').value=e.results[0][0].transcript;sendChat()};r.onerror=()=>toast('Spracheingabe klappt gerade nicht.');r.onend=()=>{if($('#micBtn'))$('#micBtn').textContent='🎤'};r.start()};\n}\nasync function sendChat(){\n  const text=$('#chatIn')?.value.trim();if(!text||chatBusy)return;\n  chat.push({role:'user',content:text});$('#chatIn').value='';chatBusy=true;renderChat();\n  try{const d=await api('/r/chat',{messages:chat.slice(-12)});chat.push({role:'assistant',content:d.reply});speak(d.reply)}\n  catch(e){toast(e.message);chat.pop();chatBusy=false;renderChat();$('#chatIn').value=text;return}\n  chatBusy=false;saveChat();renderChat();\n}\nfunction start(){$('#app').innerHTML='<div class=\"card muted\">Lade …</div>';poll();clearInterval(timer);timer=setInterval(()=>{if(!document.hidden)poll()},5000)}\n// Als App installieren: Android/Chrome zeigt einen Knopf, iPhone bekommt eine Anleitung\nlet installEv=null;const standalone=matchMedia('(display-mode: standalone)').matches||navigator.standalone;\nfunction renderInstall(){\n  const box=$('#install');if(standalone){box.innerHTML='';return}\n  if(installEv)box.innerHTML='<button class=\"primary\" id=\"instBtn\">📲 Als App installieren</button>';\n  else if(/iPhone|iPad|iPod/.test(navigator.userAgent))box.innerHTML='<div class=\"card muted\">📲 <b>Als App aufs iPhone:</b> Unten in Safari auf <b>Teilen</b> (Quadrat mit Pfeil) tippen, dann <b>Zum Home-Bildschirm</b>.</div>';\n  else box.innerHTML='<div class=\"card muted\">📲 <b>Als App aufs Handy:</b> Im Browser-Menü (⋮) auf <b>App installieren</b> oder <b>Zum Startbildschirm hinzufügen</b> tippen.</div>';\n  const b=$('#instBtn');if(b)b.onclick=async()=>{installEv.prompt();await installEv.userChoice.catch(()=>{});installEv=null;renderInstall()};\n}\naddEventListener('beforeinstallprompt',e=>{e.preventDefault();installEv=e;renderInstall()});\naddEventListener('appinstalled',()=>{installEv=null;toast('Installiert! Du findest Buddy Beast jetzt bei deinen Apps.');$('#install').innerHTML=''});\nif('serviceWorker'in navigator)navigator.serviceWorker.register('/handy/sw.js',{scope:'/handy/'}).catch(()=>{});\nrenderInstall();\ndocument.addEventListener('visibilitychange',()=>{if(!document.hidden&&token)poll()});\ntoken?start():renderPair();\n</script>\n</body>\n</html>\n";
